const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("Invalid JSON returned by AI");
}

return {
  json: {
    ...data,
    ...parsed
  }
};

const items = $input.all();

const requiredFields = [
  "Order_ID",
  "Customer_ID",
  "Customer_Name",
  "Customer_Email",
  "Product",
  "Order_Date",
  "Expected_Delivery_Days",
  "Current_Status",
  "Shipping_Team"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {

  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  const expectedDays =
    Number(data.Expected_Delivery_Days);

  const orderDate =
    new Date(data.Order_Date);

  const dateValid =
    !isNaN(orderDate.getTime());

  if (
    missingFields.length === 0 &&
    !isNaN(expectedDays) &&
    expectedDays >= 0 &&
    dateValid
  ) {

    validItems.push({
      ...data,
      Expected_Delivery_Days: expectedDays
    });

  } else {

    invalidItems.push({
      order_id:
        data.Order_ID || "Unknown",

      missing_fields:
        missingFields
    });
  }
}

return [
  {
    json: {
      data_valid:
        invalidItems.length === 0,

      total_orders:
        items.length,

      valid_orders:
        validItems.length,

      invalid_orders:
        invalidItems.length,

      invalid_details:
        invalidItems,

      order_data:
        validItems
    }
  }
];

const orders = $json.order_data;

const now = new Date();

const results = [];

for (const order of orders) {

  const orderDate =
    new Date(order.Order_Date);

  const expectedDays =
    Number(order.Expected_Delivery_Days);

  const elapsedMilliseconds =
    now.getTime() - orderDate.getTime();

  const orderAgeDays =
    elapsedMilliseconds /
    (1000 * 60 * 60 * 24);

  const remainingDays =
    expectedDays - orderAgeDays;

  const delayDays =
    Math.max(0, orderAgeDays - expectedDays);

  let orderStatus;

  // Already beyond expected delivery
  if (orderAgeDays > expectedDays) {

    orderStatus = "DELAYED";

  }

  // Within 20% of expected delivery deadline
  else if (
    remainingDays <= expectedDays * 0.20
  ) {

    orderStatus = "AT RISK";

  }

  else {

    orderStatus = "ON TIME";
  }

  results.push({

    ...order,

    Order_Age_Days:
      Number(Math.max(orderAgeDays, 0).toFixed(2)),

    Remaining_Days:
      Number(Math.max(remainingDays, 0).toFixed(2)),

    Delay_Days:
      Number(delayDays.toFixed(2)),

    Order_Status:
      orderStatus
  });
}

return [
  {
    json: {
      processed_orders:
        results
    }
  }
];

